import fs from 'node:fs'; import assert from 'node:assert/strict'; import yaml from 'js-yaml';
const paths=['.github/workflows/pr-checks.yml','.github/workflows/security.yml','.github/workflows/publish.yml']; const parsed=paths.map(path=>({path,doc:yaml.load(fs.readFileSync(path,'utf8'))}));
const steps=parsed[0].doc.jobs['setup-and-purge'].steps; const gi=steps.findIndex(s=>s.run==='node scripts/ci/verify-disposable-targets.mjs'); assert(gi>=0); const guard=steps[gi]; assert(!guard.if && !guard['continue-on-error']); for(const k of ['CORTEX_CI_DISPOSABLE_DEPLOYMENTS','CONVEX_URL','CONVEX_DEPLOY_KEY','CONVEX_URL_CLI','CONVEX_DEPLOY_KEY_CLI']) assert(guard.env[k]);
const effects=steps.flatMap((s,i)=> /convex deploy|cleanup-test-data/.test(s.run??'') ? [{i,name:s.name}] : []); assert.equal(effects.length,4); assert(effects.every(e=>e.i>gi));
for(const {doc} of parsed)for(const job of Object.values(doc.jobs))for(const s of job.steps??[])if(s.uses?.startsWith('actions/setup-node@'))assert.equal(s.with['node-version'],'24.15.0');
for(const {doc} of parsed)for(const job of Object.values(doc.jobs))for(const [i,s]of (job.steps??[]).entries())if(/npm ci/.test(s.run??'')){ const prefix=job.steps.slice(0,i+1).map(s=>s.run??'').join('\n');assert(prefix.includes('npm install --global npm@12.2.0')); }
console.log(JSON.stringify({yamlFiles:3,mandatoryGuardBeforeAllFourEffects:true,nodePins:'24.15.0',npmPins:'12.2.0',effects,liveServiceQualification:false}));
